<?php
declare(strict_types=1);
require dirname(__DIR__).'/vendor/autoload.php';
use EdFund\{Config,Database,Content,ContentImport,PostsImport,Pages,Seo,PublicCache};
$config=Config::load();$db=Database::connect($config['db']);if(!preg_match('/\Aedfund_test_[a-f0-9]{12}\z/',$db->query('SELECT DATABASE()')->fetchColumn())){throw new RuntimeException('Isolated fixture required');}
function check(bool $ok,string $label): void {if(!$ok){throw new RuntimeException($label);}echo 'PASS '.$label.PHP_EOL;}
(new ContentImport($db))->run();(new PostsImport($db,$config))->run();$pages=new Pages($db);check($pages->import()===8 && $pages->import()===0,'remaining pages import exactly once');$c=new Content($db);$seo=new Seo($db,$config);$owner=(int)$db->query('SELECT id FROM cms_users LIMIT 1')->fetchColumn();
foreach($pages->rows() as $p){$slug=$p['document_slug'];$state=$c->state($slug);$c->validate($state['content'],$slug);$html=$pages->render($slug);file_put_contents($config['storage_path'].'/'.$slug.'.html',$html);$c->change($slug,$state['version'],'publish',$state['content'],null,$owner);$meta=$seo->pageData($slug);$seo->unique($meta['title'],$meta['description'],$slug);check(true,$slug.' all imported fields publish and unique SEO validates');}
$s=$c->state('shared');$c->validate($s['content'],'shared');$c->change('shared',$s['version'],'publish',$s['content'],null,$owner);
$state=$c->state('about-us');$before=$pages->render('about-us');$cache=new PublicCache($db,$config);$key=$cache->key('/about-us/');$sitemap=$seo->sitemap();$data=$state['content'];$data['seo']['title']='About EdFund | A draft title';$draft=$c->change('about-us',$state['version'],'save',$data,null,$owner);check($key===$cache->key('/about-us/') && $before===$pages->render('about-us') && $sitemap===$seo->sitemap(),'draft saves leave cache key, public HTML and sitemap unchanged');
$pub=$c->change('about-us',$draft['version'],'publish',$data,null,$owner);check($key!==$cache->key('/about-us/'),'published snapshot invalidates public caches');$c->change('about-us',$pub['version'],'publish',$state['content'],null,$owner);
$bad=$state['content'];$bad['seo']['title']=$seo->pageData('home')['title'];try{$c->change('about-us',$c->state('about-us')['version'],'publish',$bad,null,$owner);throw new RuntimeException('Duplicate title accepted');}catch(InvalidArgumentException $expected){check(true,'duplicate published metadata rejected');}
$bad=$c->state('home')['content'];$bad['seo']['title']='Wrong homepage prefix';try{$c->validate($bad,'home');throw new RuntimeException('Homepage prefix accepted');}catch(InvalidArgumentException $expected){check(true,'homepage title prefix enforced');}
$bad=$state['content'];foreach($bad['sections'] as &$section){$t=$c->template($section['template']);foreach($t['fields'] as $k=>$f){if(($f['attribute'] ?? '')==='alt'){$section['values'][$k]='';break 2;}}}unset($section);try{$c->change('about-us',$c->state('about-us')['version'],'publish',$bad,null,$owner);throw new RuntimeException('Missing alt accepted');}catch(InvalidArgumentException $expected){check(true,'meaningful image alt required before publication');}
// Cache storage is private and bounded; failures must never prevent a public render.
foreach(range(0,70) as $i){$cache->put(hash('sha256','bounded-'.$i),str_repeat('x',2048));}
check(count(glob($config['storage_path'].'/cache/*.html'))<=64,'cache entry retention bounded to 64');
$expired=hash('sha256','expired');$cache->put($expired,'expired');touch($config['storage_path'].'/cache/'.$expired.'.html',time()-301);check($cache->get($expired)===null,'expired cache entries are ignored');
$cache->put(hash('sha256','oversize'),str_repeat('x',1048577));check(!is_file($config['storage_path'].'/cache/'.hash('sha256','oversize').'.html'),'oversize cache entry refused');
file_put_contents($config['storage_path'].'/unwritable-parent','not a directory');$badCache=new PublicCache($db,array_replace($config,['storage_path'=>$config['storage_path'].'/unwritable-parent']));$badCache->put(hash('sha256','failed-write'),'uncached');check($badCache->get(hash('sha256','failed-write'))===null,'cache write failure degrades without exception');
check(Content::url('mailto:info@edfundfoundation.org?subject=Giving%20to%20EdFund') && !Content::url('mailto:info@example.org?subject=test%0d%0aBcc:bad@example.org') && !Content::url('mailto:info@example.org?bcc=bad@example.org'),'existing email enquiry links allowed without mail-header injection');
$production=array_replace($config,['environment'=>'production','public_indexing'=>true]);$rendered=(new Seo($db,$production))->render($pages->render('home'),'/',$seo->pageData('home'));
check(str_contains($rendered,'index,follow,max-image-preview:large') && !str_contains($rendered,'noindex'),'explicit production indexing policy renders correctly');
$staging=array_replace($production,['public_indexing'=>false]);check(str_contains((new Seo($db,$staging))->render($pages->render('home'),'/',$seo->pageData('home')),'noindex,nofollow,noarchive'),'production staging stays noindex');

$gate=EdFund\ReleaseCheck::run($config,true);check($gate['checks']['one_owner_with_password'] && !isset($gate['checks']['one_owner_with_mfa']),'release preflight accepts a password owner without authenticator enrollment');
